-- Migration 035: Hauptquest Kapitel 4 „Der Brief des Königs“ und neue Aushänge für den Dorfmeister. Erzeugt von quests/amt2.py.
insert into public.items (id, name, beschreibung, art, bonus)
select 'ring_des_koenigs', 'Ring des Königs', 'Ein schmaler Ring mit dem goldenen Hirsch. Wer ihn zeigt, spricht für König Ottokar im Hügelland.', 'fund', '{"ueberreden": 1, "einschuechtern": 1}'::jsonb
where not exists (select 1 from public.items where id = 'ring_des_koenigs');

insert into public.quest_templates (id, titel, beschreibung, kurz, art, schwierigkeit, rollen, def)
select e->>'id', e->>'titel', e->>'kurz', e->>'kurz', 'chronik', (e->>'kapitel')::int, e->'rollen', e->'def' from jsonb_array_elements($q$[{"id":"chronik_4","titel":"Der Brief des Königs","kurz":"König Ottokar ruft den neuen Dorfmeister an seinen Hof nach Moosherz. Der Weg dorthin ist weiter, als es auf der Karte aussieht.","kapitel":4,"rollen":{"V":"Vorsteher","A":"Wer dich begleitet","B":"Wer das Dorf vertritt"},"def":{"start":"siegel","szenen":{"siegel":{"ort":"dorf","text":"Ein Reiter in Grün und Gold hält vor dem Langhaus. Er überreicht dir einen Brief mit dem Siegel des goldenen Hirschs: König Ottokar ruft den neuen Dorfmeister an seinen Hof nach Moosherz – zur Huldigung, „und um zu sehen, wem wir das Hügelland anvertrauen“. {A} liest über deine Schulter mit und pfeift leise.","optionen":[{"text":"„Wir brechen morgen früh auf. {A}, du kommst mit.“","weiter":"vertretung","ergebnis":"{A} grinst. „Endlich mal raus hier.“","folgen":{"sym":{"A":3}}},{"text":"Den Reiter nach Neuigkeiten aus Moosherz fragen","weiter":"reiter"}]},"reiter":{"ort":"dorf","text":"Der Reiter nimmt einen Schluck Wasser. „Der König ist alt, aber nicht dumm. Graf Wulfhard von Rabenfels hat in letzter Zeit viele Dorfmeister zu Gast. Man sagt, er schenkt großzügig.“ Er sieht dich an. „Der König will wissen, wem Ihr dient.“","optionen":[{"text":"„Wir brechen morgen früh auf.“","weiter":"vertretung","folgen":{"flag":"gewarnt"}}]},"vertretung":{"ort":"dorf","text":"Wer führt das Dorf, während du fort bist? {B} hat sich angeboten. {V} sitzt daneben und sagt nichts.","optionen":[{"text":"{B} vertritt mich","weiter":"abschied","ergebnis":"{B} richtet sich auf. „Ich passe auf, versprochen.“","folgen":{"sym":{"B":4},"flag":"vertretung_b"}},{"text":"{V} kennt das Amt – {V} vertritt mich","weiter":"abschied","ergebnis":"{V} nickt langsam. „Das ehrt mich. Geh nur.“","folgen":{"sym":{"V":5},"flag":"vertretung_v"}}]},"abschied":{"ort":"dorf","text":"Im Morgengrauen stehen die Leute am Tor. Jemand drückt dir ein Brot in die Hand, ein Kind einen Stein mit Loch – „für Glück“.","reise":{"minuten":90,"weiter":"furtenau","text":"Ihr folgt dem Silberlauf nach Süden. Die Wiesen werden weiter, die Dörfer größer."}},"furtenau":{"ort":"dorf","text":"Furtenau ist voller Wagen, die auf die Furt warten. In der Schenke am Ufer fällt dir eine Gruppe in grauen Mänteln auf. Einer fragt den Wirt ein wenig zu laut, ob „der neue Meister aus dem Hügelland“ schon durch sei.","optionen":[{"text":"Unauffällig zuhören","tag":"[Menschenkenntnis]","probe":{"id":"menschenkenntnis","dc":12},"erfolg":{"text":"Sie tragen unter den Mänteln ein Zeichen: einen schwarzen Raben. Männer aus Rabenfels – und sie warten auf dich.","weiter":"aufbruch_furt","folgen":{"flag":"raben_erkannt"}},"misserfolg":{"text":"Du verstehst nur Bruchstücke. Etwas über „den Brief“ und „die Brücke“.","weiter":"aufbruch_furt"}},{"text":"Nicht auffallen und früh weiterziehen","weiter":"aufbruch_furt"}]},"aufbruch_furt":{"ort":"wald","text":"Über die Furt, dann die alte Königsstraße entlang. Die Wälder um den Lichtwald stehen still.","reise":{"minuten":75,"weiter":"bruecke","text":"Ihr reitet abwechselnd, {A} summt ein Lied aus dem Dorf."}},"bruecke":{"ort":"wald","text":"An der Steinbrücke über den Ginsterbach versperrt ein umgestürzter Wagen den Weg. Zu ordentlich umgestürzt. Aus dem Gebüsch treten fünf Männer, Raben auf den Mänteln. „Den Brief, Meister. Und dann reitet heim.“","optionen":[{"text":"Die Waffe ziehen","weiter":"kampf"},{"text":"„Die Königswache reitet eine Stunde hinter uns.“","tag":"[Überreden]","probe":{"id":"ueberreden","dc":13},"erfolg":{"text":"Der Anführer zögert, sieht die Straße hinunter – und pfeift seine Leute zurück. „Wir sehen uns, Meister.“","weiter":"nach_bruecke","folgen":{"flag":"bluff"}},"misserfolg":{"text":"„Lüge“, sagt der Anführer ruhig. Seine Männer ziehen die Klingen.","weiter":"kampf"}},{"text":"Durchs Unterholz ausweichen","tag":"[Flink]","probe":{"id":"flink","dc":11},"erfolg":{"text":"Ihr schlagt euch ins Dickicht und kommt hinter der Brücke wieder auf die Straße. Niemand folgt euch.","weiter":"nach_bruecke"},"misserfolg":{"text":"Ein Pfeil streift {A}s Arm, aber ihr kommt durch. Das kostet Kraft und Zeit.","weiter":"nach_bruecke","folgen":{"sym":{"A":-1}}}}]},"kampf":{"ort":"wald","text":"Die Raben greifen an.","gefahr":true,"minispiel":{"art":"kampf","schwer":2,"titel":"Überfall an der Brücke","gegner":"banditen","dauer":480,"kampfort":"wald","erfolg":{"text":"Die letzten Angreifer fliehen in den Wald. Einer lässt eine Ledertasche fallen.","weiter":"tasche"},"misserfolg":{"text":"Ihr müsst zurückweichen, aber der Brief bleibt in deiner Hand. Die Raben verschwinden mit eurem Proviant.","weiter":"nach_bruecke","folgen":{"dorf":{"nahrung":-3}}}},"optionen":[]},"tasche":{"ort":"wald","text":"In der Tasche: ein Brief mit dem Rabensiegel. „Bietet dem neuen Meister des Hügellands Silber. Nimmt er an, gehört das Land bald uns. Nimmt er nicht an – sorgt dafür, dass er den König nie erreicht.“ Unterzeichnet: W.","optionen":[{"text":"Den Brief einstecken – der König soll ihn sehen","weiter":"nach_bruecke","folgen":{"flag":"rabenbrief"}},{"text":"Den Brief verbrennen – keine Händel mit Grafen","weiter":"nach_bruecke","folgen":{"flag":"brief_verbrannt"}}]},"nach_bruecke":{"ort":"wald","text":"Hinter der Brücke öffnet sich das Land. Am Abend seht ihr die Türme von Moosherz über dem Fluss.","reise":{"minuten":75,"weiter":"tor","text":"Ihr reitet schweigend. {A} sieht sich öfter um als sonst."}},"tor":{"ort":"stadt","text":"Das Südtor von Moosherz: Wachen in Grün und Gold, Händler, Bettler, Ochsenkarren. Ein Torwächter verlangt Zoll „für Fremde ohne Geleit“.","optionen":[{"text":"Das königliche Siegel zeigen","weiter":"markt","ergebnis":"Der Wächter wird blass, verbeugt sich und winkt euch durch."},{"text":"Zahlen – kein Aufsehen","weiter":"markt","ergebnis":"Zwei Ballen Tuch wechseln den Besitzer. Der Wächter grinst.","folgen":{"dorf":{"waren":-2}}}]},"markt":{"ort":"stadt","text":"Moosherz ist laut und riesig. Am Dom läuten Glocken, auf dem Markt riecht es nach Salz aus Salzwacht und Wein aus der Ostmark. Bis zur Audienz bleibt ein halber Tag.","optionen":[{"text":"Ein Geschenk für den König kaufen","weiter":"vorzimmer","ergebnis":"Ein Krug Honigwein aus dem Hügelland, in feines Leinen gebunden. Nicht teuer – aber ehrlich.","folgen":{"flag":"geschenk","dorf":{"waren":-3}}},{"text":"Den Schreiber der Kanzlei ausfindig machen","tag":"[Feilschen]","probe":{"id":"feilschen","dc":12},"erfolg":{"text":"Für ein paar Münzen verrät er dir, was der König von neuen Meistern hören will: „Wahrheit. Er hasst Schmeichler.“","weiter":"vorzimmer","folgen":{"flag":"tipp_wahrheit"}},"misserfolg":{"text":"Der Schreiber nimmt die Münzen und sagt nur: „Seid pünktlich.“","weiter":"vorzimmer"}},{"text":"Direkt zur Burg gehen","weiter":"vorzimmer"}]},"vorzimmer":{"ort":"burg","text":"Im Vorzimmer warten andere Dorfmeister: der dicke Müller aus Hollerbrück, eine strenge Frau aus Goldacker. Ein Hofmeister erklärt im Eiltempo, wer wann vortritt, wann man kniet und wie man den König anspricht.","minispiel":{"art":"merken","schwer":2,"titel":"Die Ordnung des Hofes","erfolg":{"text":"Du sagst dir alles im Kopf vor. Als dein Name fällt, weißt du genau, was zu tun ist.","weiter":"thron","folgen":{"flag":"etikette"}},"misserfolg":{"text":"Zu viel auf einmal. Du hoffst, dass dir niemand übel nimmt, wenn du einen Schritt zu früh kniest.","weiter":"thron","folgen":{"flag":"fauxpas"}},"text":"Merke dir die Reihenfolge des Hofes."},"optionen":[]},"thron":{"ort":"burg","text":"Der Thronsaal ist kühl und hoch. König Ottokar ist alt, sein Bart weiß, aber seine Augen folgen jeder Bewegung. „Das Hügelland hat also einen neuen Meister.“ Er mustert dich lange. „Wem dienst du?“","optionen":[{"text":"„Euch, mein König. Und meinem Dorf.“ – Die Treue schwören","weiter":"forderung","ergebnis":"Der König nickt knapp. „Beides zugleich. Das ist schwerer, als du denkst.“","folgen":{"gunst":10,"flag":"treue"}},{"text":"Treue schwören – und um einen Steuernachlass für den Winter bitten","tag":"[Überreden]","probe":{"id":"ueberreden","dc":14},"erfolg":{"text":"Ein Raunen geht durch den Saal. Dann lacht der König. „Mut hat er. Gut – ein Winter ohne Abgaben. Danach sehen wir weiter.“","weiter":"forderung","folgen":{"gunst":6,"flag":["treue","nachlass"]}},"misserfolg":{"text":"Das Lächeln des Königs wird dünn. „Du kommst zum ersten Mal an meinen Hof und feilschst?“ Er winkt ab.","weiter":"forderung","folgen":{"gunst":-4,"flag":"treue"}}},{"text":"Den Brief aus Rabenfels vorlegen","wenn":{"flag":"rabenbrief"},"weiter":"enthuellung"},{"text":"„Mein Dorf dient sich selbst, Majestät. Aber wir sind gute Nachbarn.“","weiter":"forderung","ergebnis":"Totenstille. Ein Höfling hustet. Der König sagt nur: „Wir werden sehen.“","folgen":{"gunst":-15,"flag":"eigenwillig","ansehen":4}}]},"enthuellung":{"ort":"burg","text":"Der König liest den Brief zweimal. Dann reicht er ihn seiner Kanzlerin, ohne den Blick von dir zu nehmen. „Wulfhard.“ Er sagt es leise, und alle im Saal werden still. „Du hättest das Silber nehmen können.“","optionen":[{"text":"„Ich habe es nicht einmal angeboten bekommen. Nur Klingen an einer Brücke.“","weiter":"rechte_hand"},{"text":"„Mein Dorf ist nicht zu verkaufen.“","weiter":"rechte_hand"}]},"rechte_hand":{"ort":"burg","text":"„Dann sollst du meine Augen und Ohren im Hügelland sein.“ Der König steht auf – zum ersten Mal an diesem Tag. „Was dort geschieht, will ich wissen, bevor es Rabenfels weiß.“ Ein Diener bringt einen schmalen Ring mit dem Hirsch.","optionen":[{"text":"Den Ring annehmen","weiter":"forderung","ergebnis":"Der Ring ist kalt und schwer. Ein Versprechen – und eine Last.","folgen":{"gunst":20,"flag":["treue","rechte_hand"],"ansehen":6,"item_plus":{"ring_des_koenigs":1}}}]},"forderung":{"ort":"burg","text":"„Nun zum Geschäft.“ Die Kanzlerin entrollt eine Karte. „Das Hügelland liegt offen zwischen Rabenfels und uns. Der König erwartet einen Beitrag.“","optionen":[{"text":"Zwei Leute für die Winterwache in Moosherz stellen","weiter":"bankett","ergebnis":"Die Kanzlerin notiert es. „Zwei kräftige Arme. Gut.“","folgen":{"gunst":6,"flag":"wache_gestellt","dorf":{"stimmung":-2}}},{"text":"Korn als Abgabe liefern","wenn":{"nicht_flag":"nachlass"},"weiter":"bankett","ergebnis":"„Zwanzig Säcke bis zum ersten Schnee.“ Das wird das Dorf spüren.","folgen":{"gunst":4,"dorf":{"nahrung":-12}}},{"text":"Eine Palisade bauen – sie schützt das Hügelland und das Königreich","weiter":"bankett","ergebnis":"Die Kanzlerin hebt eine Braue, dann nickt sie. „Ein Bollwerk an der Grenze. Der König wird es gern sehen.“ Daheim wird der Rat die Palisade als Nächstes planen.","folgen":{"gunst":5,"bau":"palisade","flag":"palisade_versprochen"}}]},"bankett":{"ort":"burg","text":"Am Abend gibt es ein Bankett. Neben dir sitzt der Gesandte der Markgräfin Ysolde aus Brandenstein, ihm gegenüber ein schweigsamer Mann mit Rabenring.","optionen":[{"text":"Mit dem Gesandten der Ostmark über Wein und Handel reden","weiter":"heimweg","ergebnis":"Er ist charmant und klug. Zum Abschied sagt er: „Brandenstein vergisst keine Freunde.“","folgen":{"flag":"ostmark_kontakt","welt":{"ort":"brandenstein","art":"handel","grund":"Wein gegen Holz aus dem Hügelland"}}},{"text":"Den Mann mit dem Rabenring beobachten","weiter":"heimweg","ergebnis":"Er verlässt das Bankett früh. Draußen wartet ein Reiter auf ihn – Richtung Norden.","folgen":{"flag":"rabe_beobachtet"}},{"text":"Früh schlafen gehen – morgen ist ein langer Ritt","weiter":"heimweg"}]},"heimweg":{"ort":"wald","text":"Im ersten Licht verlasst ihr Moosherz. Die Straße nach Norden kommt dir kürzer vor als auf dem Hinweg.","reise":{"minuten":120,"weiter":"heimkehr","text":"{A} erzählt jedem Bauern am Weg, dass „unser Meister beim König war“."}},"heimkehr":{"ort":"dorf","text":"Am Tor wartet das halbe Dorf. {B} und {V} stehen vorne. „Und?“, ruft jemand. „Was hat der König gesagt?“","optionen":[{"text":"Alles erzählen – auch von den Raben an der Brücke","weiter":"ende","ergebnis":"Die Leute hören still zu. Am Ende sagt {V}: „Dann wissen wir jetzt, wo wir stehen.“","folgen":{"sym":{"V":3,"B":2}}},{"text":"Nur sagen: „Der König vertraut uns.“","weiter":"ende","ergebnis":"Jubel. Für heute reicht das.","folgen":{"dorf":{"stimmung":3}}}]},"ende":{"ort":"dorf","text":"Abends am Feuer drehst du den Brief des Königs in der Hand. Das Hügelland liegt zwischen zwei Mächten – und dein Dorf mittendrin. Was als Nächstes kommt, wird die Chronik erzählen.","ende":true,"folgen":{"ansehen":15,"kapitel":5,"journal":["chronik_4","Der Brief des Königs","König Ottokar hat den neuen Dorfmeister des Hügellands empfangen. Graf Wulfhard von Rabenfels streckt die Hand nach dem Hügelland aus. Das Dorf liegt zwischen den Mächten."]}}},"reise":true,"ziel":"moosherz","heim":["siegel","reiter","vertretung","heimkehr","ende"]}}]$q$::jsonb) e
on conflict (id) do update set titel = excluded.titel, beschreibung = excluded.beschreibung, kurz = excluded.kurz, art = excluded.art, schwierigkeit = excluded.schwierigkeit, rollen = excluded.rollen, def = excluded.def;

insert into public.dorf_vorlagen (id, art, titel, text, optionen, rollen, auto, gewicht, bedingung)
select e->>'id', e->>'art', e->>'titel', e->>'text', e->'optionen', array(select jsonb_array_elements_text(e->'rollen')), (e->>'auto')::int, (e->>'gewicht')::numeric, e->'bedingung' from jsonb_array_elements($q$[{"id":"erbe","art":"rechtsfall","titel":"Das Erbe der alten Gerda","text":"Die alte Gerda ist gestorben. {T} und {O} streiten um ihre Hütte: {T} hat sie gepflegt, {O} ist ihr Neffe.","optionen":[{"text":"Die Hütte geht an {T}, die sie gepflegt hat","ergebnis":"{T} weint vor Erleichterung. {O} spricht wochenlang kein Wort mit dir.","folgen":{"sym":{"T":6,"O":-5}}},{"text":"Der Neffe erbt – Blut ist Blut","ergebnis":"{O} zieht ein, {T} bleibt mit leeren Händen. Viele im Dorf finden das hart.","folgen":{"sym":{"T":-6,"O":4},"stim":-1}},{"text":"Die Hütte wird geteilt: {T} wohnt, {O} bekommt den Garten","ergebnis":"Keiner ist glücklich, keiner ganz unglücklich. So ist Recht manchmal.","folgen":{"sym":{"T":2,"O":1},"stim":1}}],"rollen":["T","O"],"auto":0,"gewicht":1,"bedingung":{}},{"id":"falsches_mass","art":"rechtsfall","titel":"Das falsche Maß","text":"{O} hat beim Mehl von {T} nachgewogen: {T}s Scheffel ist kleiner als er sein sollte. {T} sagt, das Holz sei eben geschrumpft.","optionen":[{"text":"Ein neues, geeichtes Maß für alle anschaffen","ergebnis":"Ab sofort misst das ganze Dorf mit demselben Maß. Kostet etwas, spart Streit.","folgen":{"res":{"waren":-2},"stim":1}},{"text":"{T} muss den Schaden doppelt ersetzen","ergebnis":"{T} zahlt. Der Ruf ist ruiniert, das Maß jetzt richtig.","folgen":{"sym":{"T":-6,"O":3},"res":{"nahrung":3}}},{"text":"Es bei einer Ermahnung belassen","ergebnis":"{T} verspricht Besserung. {O} glaubt kein Wort.","folgen":{"sym":{"T":2,"O":-3}}}],"rollen":["T","O"],"auto":0,"gewicht":1,"bedingung":{}},{"id":"hundebiss","art":"rechtsfall","titel":"Der bissige Hund","text":"Der Hund von {T} hat das Kind von {O} gebissen. Nicht schlimm, aber {O} verlangt, dass der Hund getötet wird.","optionen":[{"text":"Der Hund muss weg","ergebnis":"{T} bringt den Hund in den Wald. Als er zurückkommt, sieht er niemanden an.","folgen":{"sym":{"T":-7,"O":4}}},{"text":"Der Hund kommt an die Kette","ergebnis":"Der Hund bellt jetzt angekettet. {O} ist halb zufrieden.","folgen":{"sym":{"T":1,"O":1}}},{"text":"{T} zahlt den Heiler und schenkt dem Kind einen Welpen","ergebnis":"Das Kind ist entzückt. {O} lacht zum ersten Mal seit Tagen.","folgen":{"sym":{"T":2,"O":4},"res":{"waren":-1},"stim":1}}],"rollen":["T","O"],"auto":0,"gewicht":1,"bedingung":{}},{"id":"wasserrecht","art":"rechtsfall","titel":"Wer bekommt das Wasser?","text":"Im Sommer hat {T} den Bach für die eigenen Beete aufgestaut. Unten bei {O} kam kaum noch etwas an. Jetzt will {O} das Wehr einreißen.","optionen":[{"text":"Feste Tage: jeder bekommt das Wasser abwechselnd","ergebnis":"Ein Wasserplan hängt am Langhaus. Erstaunlich, wie wenig dann noch gestritten wird.","folgen":{"sym":{"T":1,"O":2},"stim":2}},{"text":"Das Wehr wird eingerissen","ergebnis":"{O} jubelt, {T} flucht. Die Beete oben werden trocken.","folgen":{"sym":{"T":-5,"O":4},"res":{"nahrung":-2}}},{"text":"{T} darf stauen, muss {O} aber einen Teil der Ernte abgeben","ergebnis":"Ein Handel, der beiden etwas bringt. {O} murrt trotzdem.","folgen":{"sym":{"T":3,"O":0},"res":{"nahrung":2}}}],"rollen":["T","O"],"auto":0,"gewicht":1,"bedingung":{}},{"id":"verleumdung","art":"rechtsfall","titel":"Böse Zungen","text":"{O} erzählt überall, {T} habe beim letzten Fest die Gemeinschaftskasse angefasst. {T} verlangt, dass {O} das öffentlich zurücknimmt.","optionen":[{"text":"Die Kasse nachzählen lassen","ergebnis":"Die Kasse stimmt bis auf den letzten Pfennig. {O} muss sich entschuldigen.","folgen":{"sym":{"T":5,"O":-4},"stim":1}},{"text":"Beide zum Schweigen verpflichten","ergebnis":"Offiziell redet keiner mehr. Inoffiziell wird nun noch mehr geflüstert.","folgen":{"sym":{"T":-2,"O":-1},"stim":-1}},{"text":"{O} muss eine Woche lang den Dorfplatz fegen","ergebnis":"Das ganze Dorf sieht {O} fegen. Gelernt hat {O} etwas – geliebt wirst du dafür nicht.","folgen":{"sym":{"T":4,"O":-6}}}],"rollen":["T","O"],"auto":0,"gewicht":1,"bedingung":{}},{"id":"verlobung","art":"rechtsfall","titel":"Die gebrochene Verlobung","text":"{T} sollte im Frühjahr heiraten. Nun hat die Braut einen anderen genommen. {T} verlangt die Mitgift zurück, die schon gezahlt war.","optionen":[{"text":"Die Mitgift muss zurück","ergebnis":"{T} bekommt die Mitgift wieder. Die Braut bekommt die Schadenfreude des Dorfes.","folgen":{"sym":{"T":5},"stim":0}},{"text":"Die Hälfte – beide Familien tragen Schuld","ergebnis":"Ein Kompromiss. Am Brunnen redet man trotzdem noch monatelang darüber.","folgen":{"sym":{"T":1},"stim":1}},{"text":"Das ist Sache der Familien, nicht des Dorfes","ergebnis":"{T} hatte auf dich gehofft. Die Familien werden das unter sich regeln – laut.","folgen":{"sym":{"T":-4},"stim":-1}}],"rollen":["T"],"auto":0,"gewicht":1,"bedingung":{}},{"id":"salzhaendler","art":"handel","titel":"Der Salzhändler aus Salzwacht","text":"Ein Händler aus Salzwacht bietet einen Wagen voll Salz – genug, um den ganzen Winter Fleisch und Fisch einzulegen. Er will Holz dafür, viel Holz.","optionen":[{"text":"Salz gegen Holz tauschen","ergebnis":"Der Händler fährt mit vollem Wagen davon. Im Keller stapeln sich die Fässer mit Gepökeltem.","folgen":{"res":{"holz":-25,"nahrung":14},"welt":{"ort":"salzwacht","art":"handel","grund":"Salz gegen Holz"}}},{"text":"Nur die Hälfte nehmen","ergebnis":"Ein vorsichtiger Handel. Genug für den Winter, nicht mehr.","folgen":{"res":{"holz":-12,"nahrung":6}}},{"text":"Ablehnen – Holz brauchen wir selbst","ergebnis":"Der Händler zuckt mit den Schultern und fährt weiter nach Furtenau.","folgen":{}}],"rollen":[],"auto":0,"gewicht":1,"bedingung":{}},{"id":"kaeseband","art":"handel","titel":"Ein Bund mit Butterau","text":"Aus Butterau kommt ein Bote: Sie suchen ein Dorf, das ihnen Holz für neue Ställe liefert. Dafür bieten sie jeden Monat Käse und Butter.","optionen":[{"text":"Einschlagen – ein fester Handel","ergebnis":"Ab jetzt rollen jeden Monat Wagen zwischen den Dörfern. Die Leute freuen sich auf den Käse.","folgen":{"res":{"holz":-15,"nahrung":10},"stim":2,"welt":{"ort":"butterau","art":"handel","grund":"Holz gegen Käse und Butter"}}},{"text":"Erst einmal eine einzelne Lieferung","ergebnis":"Ein Probehandel. Der Käse ist ausgezeichnet.","folgen":{"res":{"holz":-6,"nahrung":4}}},{"text":"Ablehnen","ergebnis":"Der Bote reitet enttäuscht heim.","folgen":{}}],"rollen":[],"auto":0,"gewicht":1,"bedingung":{}},{"id":"wanderschmied","art":"handel","titel":"Der Wanderschmied","text":"Ein Schmied aus Eisgrund zieht durch und bietet an, eine Woche lang Werkzeug zu schmieden – gegen Kost, Logis und ein paar Waren.","optionen":[{"text":"Ihn aufnehmen","ergebnis":"Eine Woche lang klingt der Hammer bis in die Nacht. Danach hat jeder Bauer eine scharfe Sichel.","folgen":{"res":{"waren":-3,"nahrung":-3},"stim":2}},{"text":"Nur Kost und Logis anbieten, keine Waren","ergebnis":"Er nimmt an, arbeitet aber nur halbe Tage. Immerhin.","folgen":{"res":{"nahrung":-2},"stim":1}},{"text":"Weiterschicken","ergebnis":"Er zieht weiter nach Furtenau.","folgen":{}}],"rollen":[],"auto":0,"gewicht":1,"bedingung":{}},{"id":"pelzkauf","art":"handel","titel":"Pelzhändler aus Wolfsheim","text":"Fallensteller aus Wolfsheim bieten warme Pelze an. Der Winter wird hart, sagen sie. Sie wollen Korn.","optionen":[{"text":"Pelze für alle kaufen","ergebnis":"Niemand friert diesen Winter. Aber die Kornkammer ist sichtbar leerer.","folgen":{"res":{"nahrung":-10},"stim":3,"welt":{"ort":"wolfsheim","art":"handel","grund":"Korn gegen Pelze"}}},{"text":"Nur für die Alten und Kinder","ergebnis":"Die Schwächsten sind versorgt. Die anderen ziehen eine Lage mehr an.","folgen":{"res":{"nahrung":-4},"stim":1}},{"text":"Ablehnen – wir haben Wolle","ergebnis":"Die Fallensteller ziehen grummelnd weiter.","folgen":{}}],"rollen":[],"auto":0,"gewicht":1,"bedingung":{}},{"id":"weinangebot","art":"handel","titel":"Wein aus der Ostmark","text":"Ein Händler aus Brandenstein bietet Wein für das nächste Fest. Er sagt, die Markgräfin suche Freunde im Hügelland.","optionen":[{"text":"Wein kaufen und den Gruß erwidern","ergebnis":"Das nächste Fest wird legendär. Und in Brandenstein merkt man sich deinen Namen.","folgen":{"res":{"waren":-4},"stim":4,"welt":{"ort":"brandenstein","art":"handel","grund":"Wein für die Feste"}}},{"text":"Wein kaufen, aber keine Grüße","ergebnis":"Guter Wein, keine Politik.","folgen":{"res":{"waren":-4},"stim":3}},{"text":"Ablehnen","ergebnis":"Der Händler verabschiedet sich höflich.","folgen":{"gunst":1}}],"rollen":[],"auto":0,"gewicht":1,"bedingung":{}},{"id":"marktrecht","art":"handel","titel":"Ein eigener Markttag?","text":"{T} schlägt vor, einmal im Monat einen Markttag abzuhalten. Händler aus der Umgebung würden kommen – und Fremde, Lärm und Diebe auch.","optionen":[{"text":"Ja, einen Markttag einführen","ergebnis":"Am ersten Markttag ist das Dorf voller Stimmen. Ein paar Hühner verschwinden, aber die Kasse klingelt.","folgen":{"sym":{"T":4},"res":{"waren":4},"stim":1}},{"text":"Erst einen einzigen Versuch","ergebnis":"Ein kleiner Markt, ein paar Händler. Man wird sehen.","folgen":{"sym":{"T":2},"res":{"waren":2}}},{"text":"Nein, wir bleiben unter uns","ergebnis":"{T} ist enttäuscht. Die Alten nicken zufrieden.","folgen":{"sym":{"T":-3}}}],"rollen":["T"],"auto":0,"gewicht":1,"bedingung":{}},{"id":"furtenau_fest","art":"nachbarn","titel":"Einladung nach Furtenau","text":"Furtenau lädt zum Wettkampf ein: Stammwerfen, Seilziehen, Wettlauf. Der Gewinner bekommt ein Fass Bier – der Verlierer den Spott des ganzen Hügellands.","optionen":[{"text":"Die Stärksten schicken","ergebnis":"Eure Leute holen den Sieg im Seilziehen! Das Fass wird noch tagelang gefeiert.","folgen":{"stim":4,"ansehen":1,"welt":{"ort":"furtenau","art":"buendnis","grund":"Freunde seit dem Wettkampf"}}},{"text":"Absagen – zu viel Arbeit","ergebnis":"In Furtenau wundert man sich ein wenig.","folgen":{"stim":-1}}],"rollen":[],"auto":0,"gewicht":1,"bedingung":{}},{"id":"rabenfels_gesandter","art":"nachbarn","titel":"Ein Gesandter aus Rabenfels","text":"Ein Mann in grauem Mantel überbringt Grüße von Graf Wulfhard. Der Graf biete „Schutz und Silber“, wenn das Dorf ihm künftig Holz statt dem König Korn liefere.","optionen":[{"text":"Höflich ablehnen","ergebnis":"Der Gesandte lächelt dünn. „Der Graf hat Geduld.“","folgen":{"gunst":3}},{"text":"Das Silber nehmen, aber nichts versprechen","ergebnis":"Das Silber ist echt. In Moosherz wird man es erfahren – früher oder später.","folgen":{"res":{"waren":6},"gunst":-8}},{"text":"Den Gesandten vom Hof jagen","ergebnis":"Die Leute johlen. In Rabenfels wird man sich das merken.","folgen":{"gunst":5,"stim":2,"welt":{"ort":"rabenfels","art":"rivalitaet","grund":"Der Gesandte wurde verjagt"}}}],"rollen":[],"auto":0,"gewicht":1,"bedingung":{}},{"id":"kloster_bitte","art":"nachbarn","titel":"Bitte des Klosters","text":"Die Mönche von Kloster Morgenstern bitten um Holz für einen neuen Dachstuhl. Sie bieten an, dafür jeden Kranken aus dem Dorf aufzunehmen.","optionen":[{"text":"Holz spenden","ergebnis":"Die Mönche segnen das Dorf beim nächsten Besuch. Und sie halten Wort.","folgen":{"res":{"holz":-15},"stim":2,"welt":{"ort":"morgenstern","art":"buendnis","grund":"Holz für den Dachstuhl, Pflege für die Kranken"}}},{"text":"Holz verkaufen, nicht verschenken","ergebnis":"Die Mönche zahlen in Bier und Kräutern.","folgen":{"res":{"holz":-15,"waren":3}}},{"text":"Ablehnen","ergebnis":"Der Mönch nickt und geht. Gott verzeiht – sagt er.","folgen":{}}],"rollen":[],"auto":0,"gewicht":1,"bedingung":{}},{"id":"moorleute","art":"nachbarn","titel":"Leute aus dem Moor","text":"Drei Moorleute aus Unkenpfuhl stehen am Dorfrand und bieten Torf zum Heizen an. Viele im Dorf trauen ihnen nicht.","optionen":[{"text":"Torf kaufen","ergebnis":"Der Torf brennt langsam und warm. Und die Moorleute kommen wieder – freundlicher als gedacht.","folgen":{"res":{"waren":-2,"holz":8},"welt":{"ort":"unkenpfuhl","art":"handel","grund":"Torf für den Winter"}}},{"text":"Freundlich, aber bestimmt wegschicken","ergebnis":"Die Moorleute gehen. Einer spuckt aus.","folgen":{}}],"rollen":[],"auto":0,"gewicht":1,"bedingung":{}},{"id":"graumaentel","art":"nachbarn","titel":"Ein Mann im grauen Mantel","text":"Nachts klopft ein Mann im grauen Mantel an deine Tür. „Krähenstieg bietet Schutz. Für einen kleinen Beitrag im Jahr geschieht euren Wagen auf der Straße nichts.“","optionen":[{"text":"Zahlen – die Graumäntel fürchtet sogar der König","ergebnis":"Der Mann verschwindet so leise, wie er kam. Auf der Straße wird es ruhiger.","folgen":{"res":{"waren":-5},"welt":{"ort":"kraehenstieg","art":"furcht","grund":"Man zahlt, man schweigt"}}},{"text":"Ablehnen","ergebnis":"„Wie Ihr meint.“ Eine Woche später brennt eine Heumiete. Zufall, sagt man.","folgen":{"res":{"nahrung":-4},"stim":-2}},{"text":"Dem König melden","ergebnis":"Ein Brief geht nach Moosherz. Ob der König etwas unternimmt? Die Graumäntel jedenfalls wissen es nun.","folgen":{"gunst":6,"stim":-1}}],"rollen":[],"auto":0,"gewicht":1,"bedingung":{}},{"id":"fluechtlinge_rabenfels","art":"nachbarn","titel":"Flüchtlinge aus dem Norden","text":"Eine Familie aus einem Dorf bei Rabenfels bittet um Aufnahme. Der Graf habe ihre Abgaben verdoppelt. Nehmt ihr sie auf, wird Rabenfels das als Beleidigung sehen.","optionen":[{"text":"Aufnehmen","ergebnis":"Die Familie weint vor Dankbarkeit. In Rabenfels ist man weniger begeistert.","folgen":{"zuzug":1,"stim":1,"welt":{"ort":"rabenfels","art":"rivalitaet","grund":"Geflohene Bauern aufgenommen"}}},{"text":"Nach Moosherz weiterschicken – mit Proviant","ergebnis":"Die Familie zieht weiter. Gesehen hat dich trotzdem jeder.","folgen":{"res":{"nahrung":-3}}},{"text":"Zurückschicken","ergebnis":"Die Familie geht schweigend. Einige im Dorf schauen dich lange an.","folgen":{"stim":-2}}],"rollen":[],"auto":0,"gewicht":1,"bedingung":{}},{"id":"erntefest","art":"dorfleben","titel":"Wie feiern wir das Fest?","text":"Das Fest steht vor der Tür. {T} will ein großes Gelage, {O} meint, man solle sparen – der Winter kommt.","optionen":[{"text":"Ein großes Fest!","ergebnis":"Musik, Braten, Tanz bis zum Morgen. Die Kammer ist leerer, die Herzen voller.","folgen":{"sym":{"T":4,"O":-2},"res":{"nahrung":-8},"stim":5}},{"text":"Ein bescheidenes Fest","ergebnis":"Ein schöner Abend, aber kein großer. Alle sind zufrieden, keiner begeistert.","folgen":{"res":{"nahrung":-3},"stim":2}},{"text":"Dieses Jahr fällt das Fest aus","ergebnis":"Der Winter wird sicherer. Aber still im Dorf.","folgen":{"sym":{"T":-4,"O":3},"stim":-3}}],"rollen":["T","O"],"auto":0,"gewicht":1,"bedingung":{}},{"id":"hochzeit","art":"dorfleben","titel":"Eine Hochzeit","text":"{T} heiratet. Die Familie bittet darum, dass das Dorf ein Schwein und ein Fass Bier beisteuert – so sei es Brauch.","optionen":[{"text":"Schwein und Bier geben","ergebnis":"Die Hochzeit wird gefeiert, als gehöre das ganze Dorf zur Familie.","folgen":{"sym":{"T":6},"res":{"nahrung":-5,"waren":-1},"stim":3}},{"text":"Nur das Bier","ergebnis":"Ein fröhliches Fest, wenn auch mit weniger Braten.","folgen":{"sym":{"T":2},"res":{"waren":-1},"stim":1}},{"text":"Das zahlen die Familien selbst","ergebnis":"{T} nickt höflich. Der Tanzboden bleibt halb leer.","folgen":{"sym":{"T":-3}}}],"rollen":["T"],"auto":0,"gewicht":1,"bedingung":{}},{"id":"kinder_schule","art":"dorfleben","titel":"Wer lehrt die Kinder?","text":"{T} kann lesen und schreiben und bietet an, den Kindern im Winter Unterricht zu geben – wenn das Dorf ihm dafür Holz und Essen stellt.","optionen":[{"text":"Ja – die Kinder sollen lernen","ergebnis":"Im Langhaus sitzen bald zwölf Kinder und kritzeln Buchstaben auf Schiefer.","folgen":{"sym":{"T":5},"res":{"holz":-4,"nahrung":-3},"stim":2,"ansehen":1}},{"text":"Nur für die, deren Eltern zahlen","ergebnis":"Ein paar Kinder lernen. Die anderen schauen durchs Fenster.","folgen":{"sym":{"T":2}}},{"text":"Nein, die Kinder werden auf dem Feld gebraucht","ergebnis":"{T} seufzt. Die Kinder jubeln.","folgen":{"sym":{"T":-3}}}],"rollen":["T"],"auto":0,"gewicht":1,"bedingung":{}},{"id":"streit_nachbarn","art":"dorfleben","titel":"Lärm in der Nacht","text":"{O} beschwert sich: {T} feiert jede Nacht bis spät, singt und lärmt. {T} sagt, das Leben sei kurz.","optionen":[{"text":"Ab Mitternacht ist Ruhe","ergebnis":"Eine einfache Regel. {T} hält sich daran – meistens.","folgen":{"sym":{"T":-2,"O":3}}},{"text":"{T} darf feiern, aber nur am Wochenende","ergebnis":"Ein Kompromiss, mit dem beide leben können.","folgen":{"sym":{"T":1,"O":1},"stim":1}},{"text":"Das ist nicht deine Sache","ergebnis":"Die beiden streiten weiter. Lauter.","folgen":{"sym":{"T":1,"O":-4},"stim":-1}}],"rollen":["T","O"],"auto":0,"gewicht":1,"bedingung":{}},{"id":"heiler_streit","art":"dorfleben","titel":"Kräuter oder Gebete?","text":"{T} ist krank. {O} will ihn mit Kräutern behandeln, die Familie will lieber einen Mönch aus Morgenstern holen. Beides auf einmal geht nicht.","optionen":[{"text":"Die Kräuter von {O}","ergebnis":"{O} wacht drei Nächte. {T} wird gesund – und {O} ist plötzlich sehr gefragt.","folgen":{"sym":{"T":3,"O":5}}},{"text":"Den Mönch holen","ergebnis":"Der Mönch kommt, betet, verordnet Ruhe. {T} wird langsam gesund.","folgen":{"sym":{"T":4,"O":-3},"res":{"waren":-2}}}],"rollen":["T","O"],"auto":0,"gewicht":1,"bedingung":{}},{"id":"verirrtes_kind","art":"dorfleben","titel":"Ein Kind im Wald verirrt","text":"Das Kind von {T} ist nicht vom Beerensammeln zurückgekommen. Es wird dunkel. Die Leute warten auf dein Wort.","optionen":[{"text":"Alle suchen – sofort, mit Fackeln","ergebnis":"Um Mitternacht findet man das Kind schlafend unter einer Tanne. Das ganze Dorf lacht und weint.","folgen":{"sym":{"T":8},"stim":4,"ansehen":2}},{"text":"Nur die Jäger schicken, die anderen bleiben","ergebnis":"Die Jäger finden das Kind im Morgengrauen, durchgefroren, aber heil.","folgen":{"sym":{"T":3},"stim":1}}],"rollen":["T"],"auto":0,"gewicht":1,"bedingung":{}},{"id":"aberglaube","art":"dorfleben","titel":"Die schwarze Katze","text":"Seit {O} eine schwarze Katze hält, ist die Milch zweimal sauer geworden. Einige Leute verlangen, dass die Katze verschwindet – und {O} gleich mit.","optionen":[{"text":"Unsinn – die Katze bleibt","ergebnis":"Du stellst dich vor {O}. Die Milch wird trotzdem sauer, wenn es warm ist. Aber das Geraune verstummt.","folgen":{"sym":{"O":6},"stim":-1,"ansehen":1}},{"text":"Die Katze muss weg, {O} bleibt","ergebnis":"{O} gibt die Katze einem Bauern im Nachbardorf. Die Milch bleibt wie sie ist.","folgen":{"sym":{"O":-4},"stim":1}}],"rollen":["O"],"auto":0,"gewicht":1,"bedingung":{}},{"id":"palisade_frage","art":"bau","titel":"Ein Zaun gegen die Wildnis?","text":"{T} hat Wolfsspuren am Dorfrand gefunden. „Eine Palisade aus Pfählen – rund ums Dorf. Dann schlafen wir ruhiger.“","optionen":[{"text":"Ja – der Rat soll die Palisade als Nächstes bauen","ergebnis":"Der Rat nickt. Sobald genug Holz da ist, beginnen die Arbeiten.","folgen":{"sym":{"T":4},"bau":"palisade","stim":1}},{"text":"Noch nicht – erst Häuser und Felder","ergebnis":"{T} murmelt etwas von Wölfen, die nicht warten.","folgen":{"sym":{"T":-2}}}],"rollen":["T"],"auto":0,"gewicht":1,"bedingung":{"ohne":"palisade"}},{"id":"steinmauer_frage","art":"bau","titel":"Stein statt Holz","text":"{T} klopft gegen die Palisade. „Die hält Wölfe ab. Aber kein Heer.“ Eine Mauer aus Stein würde Jahre halten – und viel kosten.","optionen":[{"text":"Die Steinmauer planen","ergebnis":"Steinhauer messen die Linie ab. Es wird lange dauern, aber das Dorf wird eine Festung.","folgen":{"sym":{"T":4},"bau":"steinmauer"}},{"text":"Die Palisade reicht","ergebnis":"Die Pfähle bleiben. Vorerst.","folgen":{"sym":{"T":-1}}}],"rollen":["T"],"auto":0,"gewicht":1,"bedingung":{"mit":"palisade","ohne":"steinmauer"}},{"id":"brunnen_neu","art":"bau","titel":"Ein zweiter Brunnen","text":"{T} und {O} schlagen vor, am anderen Ende des Dorfes einen zweiten Brunnen zu graben. Das kostet Arbeit und Stein.","optionen":[{"text":"Graben lassen","ergebnis":"Nach zwei Wochen sprudelt frisches Wasser. Die Wege sind kürzer, die Laune besser.","folgen":{"sym":{"T":3,"O":3},"res":{"stein":-10},"stim":3}},{"text":"Später vielleicht","ergebnis":"Die beiden zucken mit den Schultern.","folgen":{}}],"rollen":["T","O"],"auto":0,"gewicht":1,"bedingung":{}},{"id":"wegebau","art":"bau","titel":"Der Weg im Schlamm","text":"Nach jedem Regen versinkt der Weg zum Feld im Schlamm. {T} will ihn mit Steinen befestigen.","optionen":[{"text":"Den Weg pflastern","ergebnis":"Ein ordentlicher Weg – endlich keine verlorenen Holzschuhe mehr.","folgen":{"sym":{"T":3},"res":{"stein":-8},"stim":2}},{"text":"Bretter auslegen reicht","ergebnis":"Die Bretter halten einen Winter. Immerhin.","folgen":{"res":{"holz":-4},"stim":1}},{"text":"Der Schlamm hat noch keinem geschadet","ergebnis":"{T} schaut auf seine Stiefel und sagt nichts.","folgen":{"sym":{"T":-2}}}],"rollen":["T"],"auto":0,"gewicht":1,"bedingung":{}},{"id":"raeuber_nacht","art":"krise","titel":"Räuber in der Nacht","text":"Heute Nacht haben Räuber zwei Ziegen und einen Sack Mehl gestohlen. {T} hat sie in Richtung Wald laufen sehen.","optionen":[{"text":"Mit den Jägern hinterher","ergebnis":"Im Morgengrauen kommen die Jäger mit den Ziegen zurück. Vom Mehl keine Spur.","folgen":{"sym":{"T":3},"res":{"nahrung":-2}}},{"text":"Nachtwachen aufstellen","ergebnis":"Ab jetzt wacht jede Nacht jemand am Tor. Gestohlen wird nichts mehr.","folgen":{"stim":1,"res":{"nahrung":-3}}},{"text":"Eine Palisade bauen – ein für alle Mal","ergebnis":"Der Rat plant die Palisade. Bis dahin hält man die Augen offen.","folgen":{"bau":"palisade","res":{"nahrung":-3}}}],"rollen":["T"],"auto":0,"gewicht":1,"bedingung":{"ohne":"palisade"}},{"id":"hagel","art":"krise","titel":"Hagel über den Feldern","text":"Ein Hagelschauer hat die halbe Ernte zerschlagen. {T} fragt, ob man die Vorräte jetzt schon rationieren soll.","optionen":[{"text":"Sofort rationieren","ergebnis":"Kleinere Portionen, längere Gesichter – aber genug bis zum Frühjahr.","folgen":{"stim":-2,"res":{"nahrung":4}}},{"text":"Erst abwarten","ergebnis":"Man hofft auf einen milden Winter.","folgen":{"res":{"nahrung":-6}}},{"text":"In Butterau Vorräte kaufen","ergebnis":"Die Wagen aus Butterau kommen gerade rechtzeitig.","folgen":{"res":{"waren":-5,"nahrung":8}}}],"rollen":["T"],"auto":0,"gewicht":1,"bedingung":{}},{"id":"brunnen_gift","art":"krise","titel":"Der Brunnen stinkt","text":"Seit gestern riecht das Wasser im Brunnen faulig. {T} hat eine tote Ratte heraufgeholt – vielleicht nicht die einzige.","optionen":[{"text":"Den Brunnen ausschöpfen und reinigen","ergebnis":"Drei Tage harte Arbeit, dann ist das Wasser wieder klar.","folgen":{"stim":1,"res":{"holz":-3}}},{"text":"Wasser vom Bach holen, bis es sich bessert","ergebnis":"Ein mühsamer Umweg – aber niemand wird krank.","folgen":{"stim":-1}}],"rollen":["T"],"auto":0,"gewicht":1,"bedingung":{}},{"id":"fuchs_huehner","art":"krise","titel":"Der Fuchs im Hühnerstall","text":"Zum dritten Mal in einer Woche hat ein Fuchs Hühner gerissen. {T} will Fallen aufstellen, {O} fürchtet um die Hunde.","optionen":[{"text":"Fallen aufstellen","ergebnis":"Nach zwei Nächten sitzt der Fuchs in der Falle. Leider vorher auch der Hund von {O}.","folgen":{"sym":{"T":3,"O":-3}}},{"text":"Den Stall besser verschließen","ergebnis":"Ein neuer Riegel, verstärkte Bretter. Der Fuchs zieht weiter.","folgen":{"res":{"holz":-3},"sym":{"T":1,"O":2}}}],"rollen":["T","O"],"auto":0,"gewicht":1,"bedingung":{}},{"id":"koenig_jagd","art":"koenig","titel":"Der König will jagen","text":"Ein Brief aus Moosherz: König Ottokar will im Herbst in den Wäldern des Hügellands jagen. Das Dorf soll Quartier und Verpflegung für sein Gefolge stellen.","optionen":[{"text":"Mit Freuden – das Beste aus Küche und Keller","ergebnis":"Der König jagt drei Tage und reist zufrieden ab. Das Dorf ist erschöpft, aber stolz.","folgen":{"gunst":10,"res":{"nahrung":-12},"stim":2}},{"text":"Annehmen, aber bescheiden","ergebnis":"Der König ist höflich. Man sieht ihm an, dass er mehr erwartet hatte.","folgen":{"gunst":3,"res":{"nahrung":-5}}},{"text":"Um Aufschub bitten – die Ernte war schlecht","ergebnis":"Der König verschiebt die Jagd. Er wird sich erinnern.","folgen":{"gunst":-4}}],"rollen":[],"auto":0,"gewicht":1,"bedingung":{}},{"id":"koenig_recht","art":"koenig","titel":"Ein Urteil des Königs","text":"Der König verlangt, dass ein Wilddieb aus dem Dorf nach Moosherz gebracht wird. {T} wurde mit einem Reh erwischt – in den königlichen Wäldern.","optionen":[{"text":"{T} ausliefern","ergebnis":"{T} wird abgeführt. Was in Moosherz geschieht, erfährt man erst im Frühjahr.","folgen":{"gunst":8,"sym":{"T":-10},"stim":-3,"verbannen":"T"}},{"text":"Eine Buße für {T} zahlen","ergebnis":"Das Dorf zahlt für {T}. Der König ist halb zufrieden, {T} ewig dankbar.","folgen":{"gunst":2,"sym":{"T":8},"res":{"waren":-6}}},{"text":"Antworten, man habe niemanden gefunden","ergebnis":"Der Bote reitet ab. Lügen haben kurze Beine – oder lange Ohren.","folgen":{"gunst":-6,"sym":{"T":5}}}],"rollen":["T"],"auto":0,"gewicht":1,"bedingung":{}},{"id":"koenig_strasse","art":"koenig","titel":"Die Königsstraße","text":"Der König will die Straße von Furtenau nach Norden ausbauen. Jedes Dorf am Weg soll zwei Wochen lang Leute zum Pflastern schicken.","optionen":[{"text":"Leute schicken","ergebnis":"Die Straße wächst. Händler kommen jetzt öfter – und schneller.","folgen":{"gunst":6,"res":{"waren":2,"nahrung":-3}}},{"text":"Stattdessen Holz liefern","ergebnis":"Der König nimmt das Holz. Die Straße wird trotzdem gebaut.","folgen":{"gunst":3,"res":{"holz":-15}}},{"text":"Ablehnen – die Felder brauchen jeden","ergebnis":"Der Bote notiert die Absage mit spitzer Feder.","folgen":{"gunst":-7}}],"rollen":[],"auto":0,"gewicht":1,"bedingung":{}},{"id":"koenig_kanzlerin","art":"koenig","titel":"Die Kanzlerin fragt nach Rabenfels","text":"Die Kanzlerin des Königs schreibt: „Was hört man im Hügelland über Graf Wulfhard? Jede Nachricht wird belohnt.“","optionen":[{"text":"Alles berichten, was man weiß","ergebnis":"Ein langer Brief geht nach Moosherz. Wenige Tage später kommt ein Beutel Silber zurück.","folgen":{"gunst":6,"res":{"waren":3}}},{"text":"Höflich antworten: Man höre nichts","ergebnis":"Die Kanzlerin schreibt nicht zurück.","folgen":{"gunst":-1}},{"text":"Antworten, das Hügelland mische sich nicht ein","ergebnis":"Neutralität ist ein Wort, das man in Moosherz nicht gern liest.","folgen":{"gunst":-5,"stim":1}}],"rollen":[],"auto":0,"gewicht":1,"bedingung":{}}]$q$::jsonb) e
